// TSV is generated by the existing Tesseract executable. It exposes coordinates
// without a second OCR engine, and is accepted only after strict numeric checks.
export function parseTesseractTsv(tsv) {
  const groups = new Map()
  const records=String(tsv||'').split(/\r?\n/).slice(1,20001)
  for(const row of records){
    const cols=row.split('\t')
    if(cols.length<12||Number(cols[0])!==5)continue
    const [page,block,paragraph,line] = cols.slice(1,5).map(Number)
    const [left,top,width,height,conf]=cols.slice(6,11).map(Number)
    const word=cols.slice(11).join('\t').replace(/\s+/g,' ').trim()
    if(!word || ![page,block,paragraph,line,left,top,width,height,conf].every(Number.isFinite) ||
      left<0||top<0||width<=0||height<=0||left+width>20000||top+height>20000||conf<0)continue
    const key=[page,block,paragraph,line].join(':')
    const record=groups.get(key)||{parts:[],box:[left,top,left+width,top+height],scores:[]}
    record.parts.push({word,x:left})
    record.box=[
      Math.min(record.box[0],left),Math.min(record.box[1],top),
      Math.max(record.box[2],left+width),Math.max(record.box[3],top+height)]
    record.scores.push(conf/100)
    groups.set(key,record)
  }
  const lines=[...groups.values()].map(g=>({
    text:g.parts.sort((a,b)=>a.x-b.x).map(x=>x.word).join(' '),
    box:g.box, score:g.scores.reduce((a,b)=>a+b,0)/g.scores.length,
  })).filter(x=>x.text&&x.score>=.35).slice(0,800)
  return {text:lines.map(x=>x.text).join('\n'),lines}
}
